const chat = $('Gmail Trigger').first().json.snippet
const agent = $input.first().json;
const respuesta = agent.output ?? agent.text ?? '';

function readCtx() {
  const names = ['Contexto Memoria Existente', 'Contexto Memoria'];
  for (const name of names) {
    try {
      const row = $(name).first().json;
      if (row && (row.Session_ID || row.user_name || row.last_summary !== undefined)) {
        return row;
      }
    } catch (e) {}
  }
  return {
    Session_ID: chat.sessionId,
    user_name: 'Usuario nuevo',
    status: 'nuevo',
    last_summary: 'Primera interacción, sin historial previo.',
    message_count: 0
  };
}

const ctx = readCtx();
const count = Number(ctx.message_count || 0) + 1;

return [{
  json: {
    Session_ID: chat.sessionId,
    user_name: ctx.user_name || 'Usuario',
    status: 'activo',
    last_summary: ctx.last_summary || 'Sin resumen previo.',
    message_count: count,
    chatInput: chat.chatInput || '',
    respuesta_agente: respuesta,
    output: respuesta
  }
}];

