// Parsea la salida JSON del AI Agent y la combina con los datos limpios del email
const allowed = ['BILLING', 'TECH_SUPPORT', 'SALES', 'UNKNOWN'];
const sources = $('4 -Set - Limpiar payload Email').all();

return $input.all().map((item, i) => {
  const raw = String(item.json.output ?? '');
  const cleaned = raw.replace(/```(?:json)?/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);

  let parsed;
  try {
    parsed = JSON.parse(match ? match[0] : cleaned);
  } catch (e) {
    parsed = { intent: 'UNKNOWN', confidence: 0, risk: 'HIGH', draft_body: '', parse_error: e.message };
  }

  const intent = allowed.includes(String(parsed.intent).toUpperCase()) ? String(parsed.intent).toUpperCase() : 'UNKNOWN';
  const src = (sources[i] ?? sources[0])?.json ?? {};

  return {
    json: {
      From: src.From ?? '',
      Subject: src.Subject ?? '',
      BodyText: src.BodyText ?? '',
      session_id: src.session_id ?? '',
      intent,
      confidence: Number(parsed.confidence ?? 0),
      risk: parsed.risk ?? 'UNKNOWN',
      draft_body: parsed.draft_body ?? '',
      parse_error: parsed.parse_error ?? null,
    },
  };
});
